INSERT OR REPLACE INTO pcs (id, brand, model_name, exact_config, category, image_url, image_alt, cpu_model, cpu_gen, cpu_cores_threads, cpu_win11_support, gpu_model, gpu_vram_gb, gpu_type, gpu_dlss_fsr, ram_gb, ram_type, ram_channel, ram_speed_mhz, storage_type, storage_capacity_gb, storage_details, motherboard_chipset, motherboard_details, psu_wattage, psu_rating, psu_details, cooling_details, os_installed, os_official_support, unverified_specs, editorial_status, created_at, updated_at) VALUES ('3d24a5b8-1da2-4fbd-af38-617ee6d72273', 'HP', '250 G9', 'Intel Core 5 120U / Intel Graphics / 16GB / 512GB', 'laptop', NULL, NULL, 'Intel Core 5 120U', 'Raptor Lake Refresh (2024)', NULL, 1, 'Intel Graphics', 0, 'integrated', NULL, 16, 'DDR4', 'dual', NULL, 'NVMe', 512, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Windows 11', 1, NULL, 'draft', 1793385959294, 1793385959294);
INSERT OR REPLACE INTO reviews (id, pc_id, slug, title, meta_title, meta_description, verdict, summary_intro, why_positive_reviews, strengths, weaknesses, evidence_level, rating_gaming, notes_gaming, rating_work, notes_work, rating_office, notes_office, amazon_listing_price_eur, estimated_fair_value_eur, status, published_at, updated_at) VALUES ('de3b20bf-3003-4129-a5e6-2006baba670e', '3d24a5b8-1da2-4fbd-af38-617ee6d72273', 'hp-250-g9-intel-core-5-120u-16gb-ram-b0dfqgdpjd', 'HP 250 G9 (Intel Core 5 120U + 16GB RAM)', 'HP 250 G9 (Intel Core 5 120U, 16GB RAM): Scheda Tecnica, Limiti e Alternative | PCChiaro', 'Recensione di HP 250 G9 (Intel Core 5 120U, Intel Graphics, 16GB DDR4, 512GB NVMe). Verdetto: Conveniente solo in offerta. Limiti reali, test e alternative.', 'conveniente_offerta', 'Notebook per uso d''ufficio, studio e smart working dotato di processore Intel a 10 core e 16 GB di RAM. La configurazione garantisce un''ottima fluidita per le attivita quotidiane, ma la valutazione favorevole e strettamente subordinata al prezzo di acquisto: a cifre superiori ai 500 Euro il rapporto qualita/prezzo decade a causa del telaio economico in plastica, dell''uscita HDMI 1.4b e del fatto che si tratta di un bundle riconfezionato da rivenditori terzi (confezione aperta e richiusa per installazione software).', NULL, '["Processore Intel Core 5 120U moderno a 10 core scattante nei compiti d''ufficio","Dotazione di 16 GB di RAM adeguata al multitasking contemporaneo con Windows 11","SSD NVMe veloce da 512 GB e tastierino numerico completo"]', '["Dispositivo riconfezionato da terzi: sigillo di fabbrica originale tagliato e confezione aperta e richiusa per installare LibreOffice","Memoria RAM di tipo DDR4 anziche il piu moderno standard DDR5 supportato dalla CPU","Porta video HDMI 1.4b datata: uscita video esterna limitata a 1080p a 60Hz o 4K a 30Hz scattosi","Prezzo sul marketplace spesso sproporzionato rispetto a modelli sigillati di fabbrica"]', 'specifiche_dichiarate', 'non_adatto', 'Grafica integrata Intel Graphics: adatta alla riproduzione multimediale e compiti 2D, non adatta al gaming 3D contemporaneo.', 'idoneo', 'Processore Intel a 10 core e 16 GB di RAM adatti a multitasking d''ufficio, fogli di calcolo complessi e videoconferenze.', 'idoneo', 'Eccellente reattivita per navigazione web con molte schede, gestione documenti e streaming video ad alta definizione.', 589, 469, 'draft', NULL, 1793385959294);
